#!/usr/bin/env bash
# Standard code test: checks submission/report.csv pulled from the remote browser.
cd /home/codio/workspace || exit 1
f=submission/report.csv
expected=$(cat <<'X'
# generated by browser-demo from data.csv
name,score,passed
alice,82,yes
bob,67,no
carol,91,yes
dave,74,yes
TOTAL,314,3
X
)
if [ ! -f "$f" ]; then
  echo "submission/report.csv not found. Download the report in the Browser tab, then run:"
  echo "  codio-tools browser pull report.csv --to submission"
  exit 1
fi
if [ "$(cat "$f")" != "$expected" ]; then
  echo "report.csv does not match the expected report:"
  diff <(echo "$expected") "$f"
  exit 1
fi
echo "report.csv is correct"
